import { LRUCache } from 'lru-cache'
import type { proto } from '../../WAProto/index.js'
import type { ILogger } from './logger.js'

/** Number of sent messages to cache in memory for handling retry receipts */
const RECENT_MESSAGES_SIZE = 512

/** Timeout for session recreation - 1 hour */
const RECREATE_SESSION_TIMEOUT = 60 * 60 * 1000 // 1 hour in milliseconds
const PHONE_REQUEST_DELAY = 500 // Reduzido de 3000ms para resposta mais rápida
export interface RecentMessageKey {
	to: string
	id: string
}

export interface RecentMessage {
	message: proto.IMessage
	timestamp: number
}

export interface SessionRecreateHistory {
	[jid: string]: number // timestamp
}

export interface RetryCounter {
	[messageId: string]: number
}

export interface PendingPhoneRequest {
	[messageId: string]: NodeJS.Timeout
}

export interface RetryStatistics {
	totalRetries: number
	successfulRetries: number
	failedRetries: number
	mediaRetries: number
	sessionRecreations: number
	phoneRequests: number
}

export class MessageRetryManager {
	private recentMessagesMap = new LRUCache<string, RecentMessage>({
		max: RECENT_MESSAGES_SIZE,
		// 🛡️ CORREÇÃO: Adicionar TTL para evitar reenvio de mensagens antigas
		// Mensagens expiram após 30 minutos, tempo suficiente para retries legítimos
		ttl: 30 * 60 * 1000, // 30 minutos
		ttlAutopurge: true  // Limpar automaticamente mensagens expiradas
	})
	
	/**
	 * 🛡️ ANTI-LOOP: Cache de timestamps de envio original
	 * Usado para determinar se um retry é legítimo (< 10s) ou se a mensagem foi apagada
	 */
	private originalSendTimes = new LRUCache<string, number>({
		max: RECENT_MESSAGES_SIZE,
		ttl: 5 * 60 * 1000, // 5 minutos
		ttlAutopurge: true
	})
	
	/**
	 * 🛡️ ANTI-LOOP: Set de mensagens já reenviadas (bloqueia reenvios futuros)
	 */
	private alreadyResentMessages = new Set<string>()
	
	/**
	 * 🛡️ ANTI-LOOP: Cache de mensagens que foram REVOGADAS (apagadas)
	 * Quando alguém apaga uma mensagem do bot, o bot não deve reenviar
	 * Tempo de vida: 10 minutos (suficiente para capturar retries após revoke)
	 */
	private revokedMessages = new LRUCache<string, number>({
		max: RECENT_MESSAGES_SIZE,
		ttl: 10 * 60 * 1000, // 10 minutos
		ttlAutopurge: true
	})
	
	private sessionRecreateHistory = new LRUCache<string, number>({
		ttl: RECREATE_SESSION_TIMEOUT * 2,
		ttlAutopurge: true
	})
	private retryCounters = new LRUCache<string, number>({
		ttl: 15 * 60 * 1000,
		ttlAutopurge: true,
		updateAgeOnGet: true
	}) // 15 minutes TTL
	private pendingPhoneRequests: PendingPhoneRequest = {}
	private readonly maxMsgRetryCount: number = 5
	private statistics: RetryStatistics = {
		totalRetries: 0,
		successfulRetries: 0,
		failedRetries: 0,
		mediaRetries: 0,
		sessionRecreations: 0,
		phoneRequests: 0
	}

	constructor(
		private logger: ILogger,
		maxMsgRetryCount: number
	) {
		this.maxMsgRetryCount = maxMsgRetryCount
	}

	/**
	 * Add a recent message to the cache for retry handling
	 * 🛡️ ANTI-LOOP: Também registra o timestamp de envio original
	 */
	addRecentMessage(to: string, id: string, message: proto.IMessage): void {
		const key: RecentMessageKey = { to, id }
		const keyStr = this.keyToString(key)
		const now = Date.now()

		// Add new message
		this.recentMessagesMap.set(keyStr, {
			message,
			timestamp: now
		})
		
		// 🛡️ ANTI-LOOP: Registrar timestamp de envio original
		this.originalSendTimes.set(id, now)

		this.logger.debug(`Added message to retry cache: ${to}/${id}`)
	}

	/**
	 * Get a recent message from the cache
	 */
	getRecentMessage(to: string, id: string): RecentMessage | undefined {
		const key: RecentMessageKey = { to, id }
		const keyStr = this.keyToString(key)
		return this.recentMessagesMap.get(keyStr)
	}
	
	/**
	 * 🛡️ ANTI-LOOP: Verifica se uma mensagem pode ser reenviada
	 * 
	 * LÓGICA CORRETA:
	 * - Bloquear se a mensagem foi REVOGADA (alguém apagou)
	 * - Bloquear se já foi reenviada uma vez (evita loop)
	 * - Permitir retry em qualquer outro caso (retry legítimo)
	 * 
	 * IMPORTANTE: Não usamos mais janela de tempo porque retries legítimos
	 * podem ocorrer a qualquer momento (latência de rede, reconexão, etc.)
	 */
	canResendMessage(messageId: string): { canResend: boolean; reason: string } {
		// Se a mensagem foi REVOGADA (apagada), NUNCA reenviar
		if (this.revokedMessages.has(messageId)) {
			return { canResend: false, reason: 'message_was_revoked' }
		}
		
		// Se já foi reenviada uma vez, não reenviar novamente
		if (this.alreadyResentMessages.has(messageId)) {
			return { canResend: false, reason: 'already_resent_once' }
		}
		
		// Permitir retry - é um retry legítimo
		return { canResend: true, reason: 'retry_allowed' }
	}
	
	/**
	 * 🛡️ ANTI-LOOP: Marca uma mensagem como REVOGADA (apagada)
	 * Isso bloqueia qualquer tentativa de reenvio futuro dessa mensagem
	 * 
	 * Deve ser chamado quando o evento REVOKE é recebido para uma mensagem do bot
	 */
	markAsRevoked(messageId: string): void {
		this.revokedMessages.set(messageId, Date.now())
		// Também remover do cache de mensagens recentes para não ocupar espaço
		this.originalSendTimes.delete(messageId)
		
		this.logger.debug(`🛡️ Message ${messageId} marked as REVOKED - blocking all future resends`)
	}

	
	/**
	 * 🛡️ ANTI-LOOP: Marca uma mensagem como já reenviada
	 * Bloqueia qualquer reenvio futuro desta mensagem
	 */
	markAsResent(messageId: string): void {
		this.alreadyResentMessages.add(messageId)
		// Limpar do cache de timestamps
		this.originalSendTimes.delete(messageId)
		
		this.logger.debug(`🛡️ Message ${messageId} marked as resent - blocking future resends`)
	}
	
	/**
	 * 🛡️ ANTI-LOOP: Bloqueia futuros reenvios de uma mensagem
	 */
	blockFutureResends(messageId: string): void {
		this.alreadyResentMessages.add(messageId)
		this.originalSendTimes.delete(messageId)
		
		this.logger.debug(`🛡️ Message ${messageId} blocked from future resends`)
	}

	/**
	 * Check if a session should be recreated based on retry count and history
	 */
	shouldRecreateSession(jid: string, retryCount: number, hasSession: boolean): { reason: string; recreate: boolean } {
		// If we don't have a session, always recreate
		if (!hasSession) {
			this.sessionRecreateHistory.set(jid, Date.now())
			this.statistics.sessionRecreations++
			return {
				reason: "we don't have a Signal session with them",
				recreate: true
			}
		}

		// Only consider recreation if retry count > 1
		if (retryCount < 2) {
			return { reason: '', recreate: false }
		}

		const now = Date.now()
		const prevTime = this.sessionRecreateHistory.get(jid)

		// If no previous recreation or it's been more than an hour
		if (!prevTime || now - prevTime > RECREATE_SESSION_TIMEOUT) {
			this.sessionRecreateHistory.set(jid, now)
			this.statistics.sessionRecreations++
			return {
				reason: 'retry count > 1 and over an hour since last recreation',
				recreate: true
			}
		}

		return { reason: '', recreate: false }
	}

	/**
	 * Increment retry counter for a message
	 */
	incrementRetryCount(messageId: string): number {
		this.retryCounters.set(messageId, (this.retryCounters.get(messageId) || 0) + 1)
		this.statistics.totalRetries++
		return this.retryCounters.get(messageId)!
	}

	/**
	 * Get retry count for a message
	 */
	getRetryCount(messageId: string): number {
		return this.retryCounters.get(messageId) || 0
	}

	/**
	 * Check if message has exceeded maximum retry attempts
	 */
	hasExceededMaxRetries(messageId: string): boolean {
		return this.getRetryCount(messageId) >= this.maxMsgRetryCount
	}

	/**
	 * Mark retry as successful
	 */
	markRetrySuccess(messageId: string): void {
		this.statistics.successfulRetries++
		// Clean up retry counter for successful message
		this.retryCounters.delete(messageId)
		this.cancelPendingPhoneRequest(messageId)
	}

	/**
	 * Mark retry as failed
	 */
	markRetryFailed(messageId: string): void {
		this.statistics.failedRetries++
		this.retryCounters.delete(messageId)
	}

	/**
	 * Schedule a phone request with delay
	 */
	schedulePhoneRequest(messageId: string, callback: () => void, delay: number = PHONE_REQUEST_DELAY): void {
		// Cancel any existing request for this message
		this.cancelPendingPhoneRequest(messageId)

		this.pendingPhoneRequests[messageId] = setTimeout(() => {
			delete this.pendingPhoneRequests[messageId]
			this.statistics.phoneRequests++
			callback()
		}, delay)

		this.logger.debug(`Scheduled phone request for message ${messageId} with ${delay}ms delay`)
	}

	/**
	 * Cancel pending phone request
	 */
	cancelPendingPhoneRequest(messageId: string): void {
		const timeout = this.pendingPhoneRequests[messageId]
		if (timeout) {
			clearTimeout(timeout)
			delete this.pendingPhoneRequests[messageId]
			this.logger.debug(`Cancelled pending phone request for message ${messageId}`)
		}
	}

	/**
	 * 🛡️ ANTI-LOOP: Remove uma mensagem do cache de retry
	 * Usado para evitar reenvios futuros de mensagens que podem ter sido apagadas
	 */
	removeFromRetryCache(to: string, id: string): void {
		const key: RecentMessageKey = { to, id }
		const keyStr = this.keyToString(key)
		
		if (this.recentMessagesMap.has(keyStr)) {
			this.recentMessagesMap.delete(keyStr)
			this.logger.debug(`🛡️ Removed message from retry cache: ${to}/${id}`)
		}
	}

	/**
	 * 🛡️ ANTI-LOOP: Verifica se uma mensagem existe no cache
	 */
	hasMessageInCache(to: string, id: string): boolean {
		const key: RecentMessageKey = { to, id }
		const keyStr = this.keyToString(key)
		return this.recentMessagesMap.has(keyStr)
	}

	/**
	 * 🛡️ ANTI-LOOP: Obtém estatísticas do cache para diagnóstico
	 */
	getCacheStats(): { size: number; stats: RetryStatistics } {
		return {
			size: this.recentMessagesMap.size,
			stats: { ...this.statistics }
		}
	}

	private keyToString(key: RecentMessageKey): string {
		return `${key.to}:${key.id}`
	}
}
